#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 5

int main(int argc, char **argv)
{
    long items[CAPACITY];
    int head = 0;
    int count = 0;

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (arg[0] == 'E') {
            char *endptr;
            long value = strtol(arg + 1, &endptr, 10);
            if (endptr == arg + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }
            if (count == CAPACITY) {
                puts("FULL");
                continue;
            }
            items[(head + count) % CAPACITY] = value;
            ++count;
            printf("ENQ %ld\n", value);
            continue;
        }
        if (arg[0] == 'D' && arg[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long value = items[head];
            head = (head + 1) % CAPACITY;
            --count;
            printf("DEQ %ld\n", value);
            continue;
        }
        if (arg[0] == 'F' && arg[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long value = items[head];
            printf("FRONT %ld\n", value);
            continue;
        }
        if (strcmp(arg, "NOOP") == 0) {
            puts("NOOP");
            continue;
        }
        puts("ERR");
    }
    return 0;
}
